insert into public.learning_questions (id, stage_id, display_order, prompt, explanation)
values
  ('aaee2904-d460-458c-a536-6699ab430e33', '70a00c90-97e8-45ab-a7a8-33fa4430549d', 1, '사탕이 접시마다 3개씩 놓여 있습니다. 모든 접시에 같은 수씩 놓인 모습은?', '접시마다 사탕이 3개로 같으므로 3개씩 묶인 모습입니다.'),
  ('9ff12a7a-6bfa-4f9b-bf52-6455145d7927', '70a00c90-97e8-45ab-a7a8-33fa4430549d', 2, '연필이 한 묶음에 2자루씩 있고 이런 묶음이 4개 있습니다. 묶음 수는?', '한 묶음에는 2자루가 있고 같은 묶음이 4개이므로 묶음 수는 4입니다.'),
  ('ec504283-f43e-4a52-a24d-e90103d6e59a', '70a00c90-97e8-45ab-a7a8-33fa4430549d', 3, '별이 한 줄에 4개씩 있고 3줄 있습니다. 같은 수를 더한 식은?', '한 줄의 별 4개를 줄 수 3번 더하므로 4+4+4입니다.'),
  ('ec5be058-8a68-4c33-a2ef-df7895ba2a66', '70a00c90-97e8-45ab-a7a8-33fa4430549d', 4, '한 봉지에 귤이 5개씩 있고 2봉지 있습니다. ''몇씩 몇 묶음''으로 나타낸 것은?', '한 봉지의 귤이 5개이고 봉지가 2개이므로 5씩 2묶음입니다.'),
  ('c04873bf-6a7f-406a-846c-ba947f4eb67e', '70a00c90-97e8-45ab-a7a8-33fa4430549d', 5, '2+2+2+2를 같은 수씩 묶은 말로 나타낸 것은?', '2를 네 번 더했으므로 한 묶음에 2개씩 4묶음입니다.'),
  ('9076b1aa-e8fd-42bd-bfc5-b68426257391', '70a00c90-97e8-45ab-a7a8-33fa4430549d', 6, '공이 상자마다 3개씩 있고 상자가 5개 있습니다. 한 묶음의 수는?', '상자 하나가 한 묶음이므로 한 묶음의 공은 3개입니다.'),
  ('a5bf319d-9315-411d-812d-dbc27de2fab4', '70a00c90-97e8-45ab-a7a8-33fa4430549d', 7, '다음 중 같은 수씩 묶여 있어 곱셈으로 나타내기 알맞은 것은?', '쟁반마다 쿠키가 3개로 같고 이런 쟁반이 4개이므로 같은 수씩 묶였습니다.'),
  ('c1e8d801-fdaf-403e-9d1c-c57a4d640256', '70a00c90-97e8-45ab-a7a8-33fa4430549d', 8, '6씩 2묶음을 반복 덧셈으로 나타낸 것은?', '한 묶음의 수 6을 묶음 수 2번 더하므로 6+6입니다.'),
  ('8bb07b1f-283d-406f-a59a-96daa86c7aa7', '70a00c90-97e8-45ab-a7a8-33fa4430549d', 9, '한 줄에 의자가 2개씩 있고 5줄 있습니다. 알맞은 설명은?', '한 줄의 의자 2개가 한 묶음이고 줄이 5개이므로 2씩 5묶음입니다.'),
  ('5dc9058a-e43d-4cda-bfd0-6461fca6347b', '70a00c90-97e8-45ab-a7a8-33fa4430549d', 10, '4+4+4에서 더해지는 같은 수와 그 수를 더한 횟수는?', '4가 세 번 더해졌으므로 같은 수는 4이고 더한 횟수는 3입니다.'),
  ('cd8c1fed-a137-48df-8433-fd5ccf0532e7', 'fa6ae6ea-128b-4559-9d63-cd26d951919d', 1, '이 단원에서는 ''3씩 4묶음''을 한 묶음의 수 × 묶음 수로 씁니다. 알맞은 곱셈식은?', '한 묶음의 수 3을 앞에, 묶음 수 4를 뒤에 써서 3×4로 나타냅니다.'),
  ('7ba7b97a-7971-44b6-91d9-b647090c8962', 'fa6ae6ea-128b-4559-9d63-cd26d951919d', 2, '한 접시에 딸기가 4개씩 있고 접시가 3개 있습니다. 알맞은 곱셈식은?', '한 묶음의 수 4를 앞에, 접시 수 3을 뒤에 써서 4×3입니다.'),
  ('22d2d91d-3ca4-4941-8986-a9ff05fa09a2', 'fa6ae6ea-128b-4559-9d63-cd26d951919d', 3, '5+5+5+5를 곱셈식으로 나타낸 것은?', '5를 네 번 더했으므로 5씩 4묶음이고 곱셈식은 5×4입니다.'),
  ('97e93bbe-c0af-48ad-b00c-aa90675401d6', 'fa6ae6ea-128b-4559-9d63-cd26d951919d', 4, '2×6이 뜻하는 것은?', '앞 수 2는 한 묶음의 수이고 뒤 수 6은 묶음 수이므로 2씩 6묶음입니다.'),
  ('b086b7a4-b374-4954-8c25-e3064b345661', 'fa6ae6ea-128b-4559-9d63-cd26d951919d', 5, '바구니 4개에 사과가 3개씩 있습니다. 3×4에서 4가 뜻하는 것은?', '3×4의 뒤 수 4는 같은 묶음인 바구니가 4개라는 뜻입니다.'),
  ('15acd98c-4120-4c51-9cc7-282d920319c5', 'fa6ae6ea-128b-4559-9d63-cd26d951919d', 6, '6×3에 알맞은 상황은?', '6×3은 한 묶음에 6개씩 3묶음이므로 상자 3개에 공이 6개씩 있는 상황입니다.'),
  ('847f1c1f-5d0b-4e83-bab9-81bbdcde32dd', 'fa6ae6ea-128b-4559-9d63-cd26d951919d', 7, '한 줄에 화분이 5개씩 있고 3줄 있습니다. 반복 덧셈과 곱셈식이 모두 알맞은 것은?', '한 줄의 5개를 줄 수 3번 더한 5+5+5이고 곱셈식은 5×3입니다.'),
  ('0d4e0904-f748-4b03-b0ce-d0e829948f3b', 'fa6ae6ea-128b-4559-9d63-cd26d951919d', 8, '4×2를 읽고 뜻을 바르게 말한 것은?', '4×2는 ''사 곱하기 이''라고 읽고 4씩 2묶음을 뜻합니다.'),
  ('b2003b05-45fa-420a-b461-d67a5e675498', 'fa6ae6ea-128b-4559-9d63-cd26d951919d', 9, '공책을 2권씩 4명에게 나누어 줍니다. 알맞은 곱셈식은?', '한 사람에게 주는 2권이 한 묶음이고 사람이 4명이므로 2×4입니다.'),
  ('07d91a08-cb18-4301-8cda-5d19670f260b', 'fa6ae6ea-128b-4559-9d63-cd26d951919d', 10, '3×5에서 3이 뜻하는 것은?', '곱셈식의 앞 수 3은 한 묶음에 들어 있는 수를 뜻합니다.'),
  ('07694bd8-16a5-43a4-8eb5-92cf1f5323c0', '88c82137-760d-4e35-a407-046a5eb0ba6c', 1, '한 줄에 별이 4개씩 5줄 있습니다. 식과 설명이 알맞게 짝지어진 것은?', '한 줄의 4개가 5줄 있으므로 4씩 5묶음이고 식은 4×5입니다.'),
  ('cc865498-8cea-49a5-b943-97962a857c50', '88c82137-760d-4e35-a407-046a5eb0ba6c', 2, '사탕이 모두 18개이고 한 봉지에 6개씩 담았습니다. 봉지는 몇 개입니까?', '6개씩 3봉지는 6+6+6=18이므로 봉지는 3개입니다.'),
  ('82d3f527-70f3-409a-a44b-5052aaece093', '88c82137-760d-4e35-a407-046a5eb0ba6c', 3, '연필이 모두 20자루이고 4묶음에 똑같이 들어 있습니다. 한 묶음에는 몇 자루입니까?', '5자루씩 4묶음은 5+5+5+5=20이므로 한 묶음에는 5자루입니다.'),
  ('1a514908-00cd-4e91-ae68-3e63383e14b1', '88c82137-760d-4e35-a407-046a5eb0ba6c', 4, '3×4에 맞는 반복 덧셈은?', '3×4는 한 묶음의 수 3을 묶음 수 4번 더한 3+3+3+3입니다.'),
  ('c5637ee5-6a05-4ffa-8744-fea68afd3106', '88c82137-760d-4e35-a407-046a5eb0ba6c', 5, '다음 중 2×5로 나타낼 수 있는 상황은?', '꽃 2송이가 한 묶음이고 꽃병이 5개이므로 2씩 5묶음인 2×5입니다.'),
  ('467a824e-bf92-44bc-9994-fc97f0d9200a', '88c82137-760d-4e35-a407-046a5eb0ba6c', 6, '민수는 4씩 3묶음을 3×4라고 썼습니다. 잘못된 까닭은?', '이 단원에서는 한 묶음의 수를 앞에 쓰므로 4씩 3묶음은 4×3입니다.'),
  ('d2ea8a50-a9b2-4fb3-9183-1a7586563c24', '88c82137-760d-4e35-a407-046a5eb0ba6c', 7, '2+2+2+2+2를 2×4라고 쓴 설명에서 잘못된 부분은?', '2가 다섯 번 더해졌으므로 묶음 수는 5이고 알맞은 식은 2×5입니다.'),
  ('b5809bd6-765c-4f8f-9d04-730530eff3b0', '88c82137-760d-4e35-a407-046a5eb0ba6c', 8, '쟁반마다 쿠키가 4개씩 있습니다. 4×□=4+4+4에서 □에 알맞은 수는?', '오른쪽에서 4가 세 번 더해졌으므로 묶음 수를 나타내는 □는 3입니다.'),
  ('176534b3-274d-441d-9733-5fd6a3731c1b', '88c82137-760d-4e35-a407-046a5eb0ba6c', 9, '2씩 6묶음과 같은 전체 수를 만들지만 묶는 방법이 다른 것은?', '2씩 6묶음은 12이고 3씩 4묶음도 12이지만 한 묶음의 수와 묶음 수가 다릅니다.'),
  ('fe4b5d39-cd09-422e-8855-8785342c5a72', '88c82137-760d-4e35-a407-046a5eb0ba6c', 10, '컵이 15개이고 한 줄에 3개씩 놓습니다. 알맞은 곱셈식은?', '3개씩 놓은 줄이 5줄이므로 한 묶음의 수 × 묶음 수는 3×5입니다.'),
  ('2e03ece4-bcca-4c15-b01d-7921fee22ae0', '6559b39d-f80a-4ed6-a5e7-01c5e800e210', 1, '4×3을 나타내는 상황과 이유가 모두 알맞은 것은?', '4×3은 한 묶음에 4개씩 3묶음이고 반복 덧셈은 4+4+4입니다.'),
  ('99dbcb22-524b-4231-b16c-ff4f188a29d2', '6559b39d-f80a-4ed6-a5e7-01c5e800e210', 2, '상자 4개에 공이 3개씩 있습니다. 4×3이라고 쓴 학생의 생각을 바르게 고친 것은?', '한 묶음인 상자 하나의 공 3개를 앞에, 상자 수 4를 뒤에 써서 3×4입니다.'),
  ('c3a4ebc2-f202-4310-a9fd-a77691af74e8', '6559b39d-f80a-4ed6-a5e7-01c5e800e210', 3, '한 봉지에 구슬이 5개씩 있습니다. 구슬 20개를 모두 담으려면 식의 □는 얼마입니까? 5×□', '5개씩 4봉지는 5+5+5+5=20이므로 □는 4입니다.'),
  ('6e7062b1-f082-43d2-93f8-250d9c139610', '6559b39d-f80a-4ed6-a5e7-01c5e800e210', 4, '다음 중 3×4와 전체 수는 같지만 묶음의 뜻은 다른 설명은?', '4씩 3묶음도 전체는 12이지만 한 묶음의 수와 묶음 수가 3×4와 서로 다릅니다.'),
  ('e6f9b58a-0b52-463f-a0b7-36561a74952e', '6559b39d-f80a-4ed6-a5e7-01c5e800e210', 5, '한 줄에 2개씩 6줄 놓인 단추를 3개씩 다시 묶었습니다. 알맞은 설명은?', '처음 2씩 6묶음과 다시 만든 3씩 4묶음은 묶는 방법은 달라도 전체가 12개로 같습니다.'),
  ('d85b9399-dd4c-454e-b039-3fcc665b4399', '6559b39d-f80a-4ed6-a5e7-01c5e800e210', 6, '7×3을 설명한 것 중 잘못된 것은?', '3씩 7묶음은 3×7의 뜻입니다. 7×3은 7씩 3묶음입니다.'),
  ('f1c4c7b6-8f54-4bd2-83a2-d106ed25a761', '6559b39d-f80a-4ed6-a5e7-01c5e800e210', 7, '접시마다 빵이 같은 수씩 있고 접시는 4개입니다. 빵이 모두 24개라면 한 접시의 빵 수와 식은?', '24개를 4접시에 똑같이 놓으면 한 접시에 6개씩이고 식은 6×4입니다.'),
  ('9ad06fd3-3ac8-4aae-96a8-943445542a62', '6559b39d-f80a-4ed6-a5e7-01c5e800e210', 8, '''2×5는 2와 5를 더한 7이다''라는 설명을 바르게 고친 것은?', '2×5는 2씩 5묶음이므로 2를 다섯 번 더한 식으로 뜻을 설명합니다.'),
  ('ad8c349d-bf63-4abd-b7a5-4146136a8151', '6559b39d-f80a-4ed6-a5e7-01c5e800e210', 9, '한 칸에 별이 4개씩 있는 칸이 3개, 한 칸에 별이 2개씩 있는 칸이 6개입니다. 알맞은 설명은?', '4씩 3묶음과 2씩 6묶음은 모두 12개이지만 묶음의 모양은 다릅니다.'),
  ('914ed9cc-704f-431e-aa39-0a764c46aee9', '6559b39d-f80a-4ed6-a5e7-01c5e800e210', 10, '3+3+3+3과 어떤 상황을 연결한 설명이 가장 알맞습니까?', '3이 네 번 더해졌으므로 3씩 4묶음이고 곱셈식은 3×4입니다.');

