  ('c9808d40-411f-4c5e-b0bc-f00358614cb7', 'ec5be058-8a68-4c33-a2ef-df7895ba2a66', 2, '5씩 5묶음', false),
  ('51934eb2-f217-464f-ba5d-c0167b1309cd', 'ec5be058-8a68-4c33-a2ef-df7895ba2a66', 3, '2씩 2묶음', false),
